import React, { useState } from 'react';
import TimeBlock from './TimeBlock';

function DayPlanner({ date, entries, setEntries }) {
  const dateKey = date.toDateString();
  const dayEntry = entries[dateKey] || { morning: [], day: [], evening: [] };

  const timeBlocks = [
    {
      id: 'morning',
      title: '🌅 Утро',
      timeRange: '06:00 - 12:00',
      icon: '☀️',
      period: 'утро'
    },
    {
      id: 'day',
      title: '☀️ День',
      timeRange: '12:00 - 18:00',
      icon: '🌤️',
      period: 'день'
    },
    {
      id: 'evening',
      title: '🌙 Вечер',
      timeRange: '18:00 - 00:00',
      icon: '🌙',
      period: 'вечер'
    }
  ];

  const handleBlockUpdate = (blockId, items) => {
    setEntries({
      ...entries,
      [dateKey]: {
        ...dayEntry,
        [blockId]: items
      }
    });
  };

  const handlePrevDay = () => {
    const prevDay = new Date(date);
    prevDay.setDate(date.getDate() - 1);
    setEntries(entries); // Просто обновляем дату, entries остаются
    // Но нам нужно обновить date в родительском компоненте
    // Для этого нужно передать setSelectedDate из App
    // Временно используем window.location reload для простоты
    window.location.reload(); // Временно, потом нужно будет передать setSelectedDate
  };

  const handleNextDay = () => {
    const nextDay = new Date(date);
    nextDay.setDate(date.getDate() + 1);
    window.location.reload(); // Временно
  };

  return (
    <div className="day-planner">
      <div className="day-navigation">
        <button onClick={handlePrevDay} className="nav-btn">←</button>
        <h2>
          {date.toLocaleDateString('ru-RU', {
            weekday: 'long',
            year: 'numeric',
            month: 'long',
            day: 'numeric'
          })}
        </h2>
        <button onClick={handleNextDay} className="nav-btn">→</button>
      </div>

      <div className="time-blocks">
        {timeBlocks.map(block => (
          <TimeBlock
            key={block.id}
            id={block.id}
            title={block.title}
            timeRange={block.timeRange}
            icon={block.icon}
            period={block.period}
            items={dayEntry[block.id]}
            onUpdate={(items) => handleBlockUpdate(block.id, items)}
          />
        ))}
      </div>
    </div>
  );
}

export default DayPlanner;
